insert into public.products
  (id, name, short_description, description, image_url, image_alt, categories, price_from, lead_time_days, badges, details, quantity_label, quantity_unit, quantity_options, sort_order)
values
  ('kit-mesa-posta', 'Jogo Americano & Sousplat de Crochê', 'Kit Mesa Posta em fio de malha com acabamento trabalhado.', 'Jogo em fio de malha/barbante com acabamento trabalhado. Deixa a mesa do café ao jantar com cara de casa de vó — só que moderna. Cada lugar acompanha jogo americano e sousplat combinando.', '/images/jogo-americano.jpg', 'Jogos americanos de crochê em tom cru dispostos lado a lado', array['mesa']::text[], 189, 5, array['Mais Pedido']::text[], array['Barbante 100% algodão', 'Sousplat de 35 cm', 'Jogo americano 45 × 30 cm']::text[], 'Quantidade de lugares', 'lugares', array[4, 6, 8]::integer[], 10),
  ('jogo-banheiro-oval', 'Tapete de Banheiro Oval em Crochê', 'Jogo de banheiro 3 peças em algodão macio.', 'Jogo de banheiro 3 peças em algodão macio: tapete oval, tampa de vaso e contorno. Fofinho para pisar, firme para não escorregar e lindo em qualquer cantinho.', '/images/tapete.jpg', 'Tapete redondo de crochê em tons terrosos e azuis sobre o piso', array['banheiro']::text[], 159, 7, array['Feito sob Medida']::text[], array['3 peças', 'Algodão macio', 'Pode ir à máquina no ciclo delicado']::text[], 'Quantidade de jogos', 'jogo(s)', array[1, 2, 3]::integer[], 20),
  ('bolsa-verao', 'Bolsa de Crochê Verão / Casual', 'Bolsa moderna em crochê estruturado com alça resistente.', 'Bolsa moderna feita em crochê estruturado com alça resistente. Leve para a feira, a praia ou o passeio de domingo — cabe tudo e ainda arranca elogios.', '/images/bolsa.jpg', 'Bolsa de crochê em trama aberta pendurada em um gancho', array['bolsas', 'pronta-entrega']::text[], 129, null, array['Pronta Entrega', 'Novidade']::text[], array['Alça reforçada', 'Trama aberta e leve', 'Aprox. 35 × 40 cm']::text[], 'Quantidade', 'unidade(s)', array[1, 2, 3]::integer[], 30),
  ('cesto-organizador', 'Cesto Organizador Multiuso', 'Cesto em fio de malha para quarto de bebê ou sala.', 'Cesto em fio de malha para quarto de bebê ou organização de sala. Guarda fraldas, brinquedos, mantas e revistas com charme e aconchego.', '/images/cesto.jpg', 'Cesto de crochê com quadradinhos coloridos e um ursinho de crochê dentro', array['infantil', 'pronta-entrega']::text[], 89, null, array['Pronta Entrega']::text[], array['Fio de malha', 'Estrutura firme', 'Disponível em P, M e G']::text[], 'Quantidade', 'unidade(s)', array[1, 2, 3]::integer[], 40),
  ('centro-de-mesa-rendado', 'Centro de Mesa em Crochê Rendado', 'Peça elegante em pontilhado delicado para mesa de jantar.', 'Peça elegante em pontilhado delicado para mesa de jantar. Um clássico que atravessa gerações e deixa a casa pronta para receber.', '/images/centro-mesa.jpg', 'Centro de mesa redondo de crochê rendado em linha cru', array['mesa']::text[], 119, 6, array['Mais Pedido']::text[], array['Linha 100% algodão', 'Aprox. 60 cm de diâmetro', 'Bordas em leque']::text[], 'Quantidade', 'unidade(s)', array[1, 2, 3]::integer[], 50),
  ('amigurumi-ursinho', 'Ursinho Amigurumi', 'Bichinho de crochê fofinho, perfeito para presentear.', 'Ursinho amigurumi com enchimento antialérgico e olhinhos com trava de segurança. Companheiro de soneca e lembrança para a vida toda.', '/images/amigurumi.jpg', 'Ursinho de crochê vermelho com flor na cabeça e blusinha listrada', array['infantil']::text[], 99, 10, array['Novidade']::text[], array['Enchimento antialérgico', 'Olhos com trava de segurança', 'Aprox. 25 cm']::text[], 'Quantidade', 'unidade(s)', array[1, 2, 3]::integer[], 60),
  ('kit-porta-copos', 'Kit Porta-Copos Listrado', 'Porta-copos em crochê tunisiano, prontinho para enviar.', 'Porta-copos em crochê tunisiano com listras alegres. Protege a mesa e dá aquele toque artesanal no cafezinho da tarde.', '/images/porta-copos.jpg', 'Porta-copos de crochê amarelo-claro com listras vermelhas', array['mesa', 'pronta-entrega']::text[], 49, null, array['Pronta Entrega']::text[], array['Crochê tunisiano', 'Aprox. 12 × 12 cm', 'Kit com estojo de presente']::text[], 'Peças no kit', 'peças', array[4, 6, 8]::integer[], 70)
